class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        if (nums.empty()) return 0;
        vector<int> expected;
        expected.push_back(nums[0]);
        for (int i = 1; i < (int)nums.size(); ++i) {
            if (nums[i] != nums[i-1]) expected.push_back(nums[i]);
        }
        for (int i = 0; i < (int)expected.size(); ++i) nums[i] = expected[i];
        return (int)expected.size();
    }
};

