from typing import List
class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        if not nums:
            return 0
        expected = [nums[0]]
        for i in range(1, len(nums)):
            if nums[i] != nums[i-1]:
                expected.append(nums[i])
        for i in range(len(expected)):
            nums[i] = expected[i]
        return len(expected)

